<?php
require_once __DIR__.'/../../config/config.php';
require_once __DIR__.'/../../includes/account_monitoring.php';
require_role('admin');$db=getDB();$u=current_user();
if(!is_primary_admin($u)&&!has_admin_permission('manage_users',$u,$db)&&!has_admin_permission('approve_users',$u,$db))admin_access_denied();
if($_SERVER['REQUEST_METHOD']!=='GET'){http_response_code(405);exit('Directory is read-only. Use the authorized security exception process.');}
foreach(['tab','role','search','page','view'] as $key)if(isset($_GET[$key])&&!is_scalar($_GET[$key])){http_response_code(400);exit('Invalid directory filter.');}
$pageTitle='People Directory & Account Monitoring';$includeAdmins=is_primary_admin($u);
$monitor=new AccountMonitoringService($db);$pageError='';$historyError='';
$stats=['total'=>0,'active'=>0,'inactive'=>0,'verification'=>0];$directory=['rows'=>[],'total'=>0,'page'=>1,'pages'=>1];
try {$stats=$monitor->counts($includeAdmins);$directory=$monitor->directory($_GET,$includeAdmins);}
catch(PDOException $e){error_log('People directory unavailable; SQLSTATE='.(string)$e->getCode());http_response_code(503);$pageError='People Management is temporarily unavailable. Please retry or ask MIS support to check the deployed database schema.';}
$canSecurity=is_primary_admin($u)||(has_admin_permission('manage_security',$u,$db)&&has_admin_permission('manage_users',$u,$db));
function people_url(array $changes=[]): string {return '?'.http_build_query(array_merge(array_intersect_key($_GET,array_flip(['tab','role','search','page'])),$changes));}
$detail=null;foreach($directory['rows'] as $person)if((int)($person['id'])===(int)($_GET['view']??0))$detail=$person;
$history=[];
if($detail) {
    try {
        $q=$db->prepare("SELECT event_type AS action,details,occurred_at AS recorded_at FROM account_security_events WHERE user_id=? UNION ALL SELECT action,details,created_at AS recorded_at FROM activity_logs WHERE user_id=? AND module='auth' ORDER BY recorded_at DESC LIMIT 30");
        $q->execute([$detail['id'],$detail['id']]);$history=$q->fetchAll();
    }catch(PDOException $e){error_log('People account history unavailable; SQLSTATE='.(string)$e->getCode());$historyError='Account history is temporarily unavailable. No account data was changed.';}
}
?>
<!DOCTYPE html><html lang="en"><head><?php include __DIR__.'/../../includes/head.php'; ?></head><body>
<div class="app-wrapper"><?php include __DIR__.'/../../components/sidebar.php'; ?><div class="main-content"><?php include __DIR__.'/../../components/navbar.php'; ?><main class="content-area page-enter">
<div class="app-page-head d-flex flex-wrap justify-content-between gap-3"><div><h1 class="h4 fw-bold">People Directory &amp; Account Monitoring</h1><p class="small text-muted mb-0">Account visibility, verification status and security oversight. Access changes follow a documented exception process.</p></div><div class="d-flex gap-2 align-items-start"><?php if($canSecurity): ?><a class="btn btn-sm btn-outline-primary" href="account_exceptions.php">Security exceptions</a><?php endif; ?><a class="btn btn-sm btn-outline-secondary" href="../ai_assistant.php">MICA monitoring</a></div></div>
<?php if($pageError): ?><div class="alert alert-danger" role="alert"><?=e($pageError)?></div><?php endif; ?>
<div class="row g-3 mb-3"><?php foreach(['total'=>'Total Registered Users','active'=>'Active Accounts','inactive'=>'Inactive Accounts','verification'=>'Accounts Requiring Verification'] as $key=>$label): ?><div class="col-6 col-xl-3"><div class="card border-0 shadow-sm p-3"><span class="text-muted small"><?=e($label)?></span><strong class="fs-3"><?=$pageError?'Unavailable':$stats[$key]?></strong></div></div><?php endforeach; ?></div>
<p class="small text-muted">Total = active + inactive + requiring verification. Inactive includes rejected and other non-active terminal statuses. Email OTP automatically activates Student and Teacher basic accounts. Clinical staff provisioning is separate. <?= $includeAdmins?'All accounts are included.':'Administrator accounts are outside your directory scope; all counts use the same scope.' ?></p>
<?php if($detail): $detail['state_label']=AccountMonitoringService::statusLabel($detail); ?><section class="card p-3 mb-3" aria-labelledby="people-detail"><div class="d-flex justify-content-between"><h2 id="people-detail" class="h6">Account details: <?=e($detail['first_name'].' '.$detail['last_name'])?></h2><a href="<?=e(people_url())?>" aria-label="Close details">Close</a></div><dl class="row small mb-0"><?php foreach(['id'=>'Account ID','username'=>'Username','role'=>'Role','identifier'=>'Institutional identifier','state_label'=>'Account status','email_verified_at'=>'Email verified at','self_service_only'=>'Personal services only','registration_status'=>'Registration assessment','validation_reason'=>'Verification evidence / review reason','created_at'=>'Registered','last_login'=>'Last sign-in'] as $key=>$label): ?><dt class="col-sm-4"><?=e($label)?></dt><dd class="col-sm-8"><?=e($detail[$key]??'Not recorded')?></dd><?php endforeach; ?></dl><p class="small mb-0">Email ownership: <?=$detail['email_verified']?'Recorded as verified':'Not verified'?>. QR availability does not imply permission to sign in.</p></section><?php endif; ?>
<?php if($detail): ?><section class="card p-3 mb-3" aria-labelledby="people-history"><h2 class="h6" id="people-history">Recent account activity and verification history</h2><?php if($historyError): ?><p class="small text-danger mb-0" role="alert"><?=e($historyError)?></p><?php elseif(!$history): ?><p class="small text-muted mb-0">No activity recorded.</p><?php else: ?><ul class="small mb-0"><?php foreach($history as $event): ?><li><time><?=e($event['recorded_at'])?></time> — <?=e($event['action'])?>: <?=e($event['details']??'')?></li><?php endforeach; ?></ul><?php endif; ?><?php if($canSecurity): ?><a class="small mt-2" href="security.php">Investigate, suspend or restore through Security Center</a><?php endif; ?></section><?php endif; ?>
<form method="get" class="card border-0 shadow-sm p-3 mb-3"><div class="row g-2 align-items-end"><div class="col-sm-6 col-lg-5"><label class="form-label small" for="people-search">Search name, username, email or identifier</label><input id="people-search" name="search" class="form-control form-control-sm" maxlength="120" value="<?=e($_GET['search']??'')?>"></div><div class="col-sm-3 col-lg-2"><label class="form-label small" for="people-role">Role</label><select id="people-role" name="role" class="form-select form-select-sm"><?php foreach([''=>'All roles','student'=>'Student','teacher'=>'Teacher','nurse'=>'Nurse']+($includeAdmins?['admin'=>'Administration']:[]) as $value=>$label): ?><option value="<?=e($value)?>" <?=($_GET['role']??'')===$value?'selected':''?>><?=e($label)?></option><?php endforeach; ?></select></div><div class="col-sm-3 col-lg-3"><label class="form-label small" for="people-status">Account state</label><select id="people-status" name="tab" class="form-select form-select-sm"><?php foreach(['all'=>'All states','active'=>'Active','inactive'=>'All inactive states','pending'=>'All requiring verification','email_pending'=>'Email Verification Pending','activation_pending'=>'Activation Pending','staff_pending'=>'Basic Nurses (Clinical Access Restricted)','suspended'=>'Suspended','rejected'=>'Rejected'] as $value=>$label): ?><option value="<?=$value?>" <?=($_GET['tab']??'all')===$value?'selected':''?>><?=$label?></option><?php endforeach; ?></select></div><div class="col-lg-2 d-flex gap-2"><button class="btn btn-sm btn-primary">Apply</button><a href="users.php" class="btn btn-sm btn-outline-secondary">Reset</a></div></div></form>
<div class="card p-3 border-0 shadow-sm"><div class="table-responsive" role="region" aria-label="People directory" tabindex="0"><table class="table table-hover align-middle"><thead><tr><th scope="col">Person / username</th><th scope="col">Role</th><th scope="col">Institutional identifier</th><th scope="col">Email ownership</th><th scope="col">QR availability</th><th scope="col">Account status</th><th scope="col">Registered</th><th scope="col">Details</th></tr></thead><tbody>
<?php foreach($directory['rows'] as $person): ?><tr><td><strong><?=e($person['first_name'].' '.$person['last_name'])?></strong><div class="small text-muted">@<?=e($person['username'])?></div></td><td><?=e(get_role_display_name($person['role']))?></td><td><?=e($person['identifier']??'Not applicable')?></td><td><div class="small"><?=e($person['email'])?></div><span class="badge <?=$person['email_verified']?'bg-success':'bg-warning text-dark'?>"><?=$person['email_verified']?'Verified':'Not verified'?></span></td><td><?=in_array($person['role'],['student','teacher'],true)?($person['has_qr']?'Available':'Not available'):'Not applicable'?></td><td><span class="badge <?=$person['status']==='active'?'bg-success':($person['status']==='pending'?'bg-warning text-dark':'bg-secondary')?>"><?=e(AccountMonitoringService::statusLabel($person))?></span></td><td class="small"><?=e($person['created_at'])?></td><td><a class="btn btn-sm btn-outline-primary" href="<?=e(people_url(['view'=>(int)$person['id']]))?>" aria-label="View details for <?=e($person['username'])?>">View Details</a></td></tr><?php endforeach; ?>
<?php if(!$directory['rows']): ?><tr><td colspan="8" class="text-center text-muted py-4"><?= $pageError ? 'Directory results are unavailable.' : 'No people match these filters.' ?></td></tr><?php endif; ?></tbody></table></div><nav class="d-flex flex-wrap justify-content-between align-items-center gap-2" aria-label="Directory pagination"><span class="small text-muted"><?=$directory['total']?> matching records · Page <?=$directory['page']?> of <?=$directory['pages']?></span><div class="d-flex gap-2"><?php if($directory['page']>1): ?><a class="btn btn-sm btn-outline-secondary" href="<?=e(people_url(['page'=>$directory['page']-1]))?>">Previous</a><?php endif; ?><?php if($directory['page']<$directory['pages']): ?><a class="btn btn-sm btn-outline-secondary" href="<?=e(people_url(['page'=>$directory['page']+1]))?>">Next</a><?php endif; ?></div></nav></div>
</main></div></div><?php include __DIR__.'/../../components/footer.php'; ?></body></html>
